-- 钓点：原版「钓鱼物品=物品名*数量|」
INSERT OR IGNORE INTO gather_point (map_id, kind, name, item_id, qty_min, qty_max, need_item, refresh, level_req, enabled)
  SELECT id, 'fish', '圣魂村·钓点', COALESCE((SELECT id FROM item WHERE name = '复活币'), 0), 1, 2, 0, 1, 1, 1 FROM map WHERE name = '圣魂村';

